const lessons=[{"sentences":[{"speaker":"A","text":"Good morning because I missed my morning train I need to change this ticket for a later service.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.623541666666667},{"speaker":"B","text":"Good morning and do you know that standard tickets usually charge a small administration fee for any changes?","position":2,"audioStartSeconds":5.823541666666666,"audioEndSeconds":12.1945},{"speaker":"A","text":"Although I did not know about that fee I am happy to pay it if I can travel this afternoon.","position":3,"audioStartSeconds":12.3945,"audioEndSeconds":17.588583333333332},{"speaker":"B","text":"Let me check the computer system when you hand me your booking reference number.","position":4,"audioStartSeconds":17.78858333333333,"audioEndSeconds":22.51875},{"speaker":"A","text":"Here is my card and my booking reference is printed right at the top of the paper receipt.","position":5,"audioStartSeconds":22.71875,"audioEndSeconds":28.066708333333334},{"speaker":"B","text":"Thank you because I see your original reservation successfully on the screen right now.","position":6,"audioStartSeconds":28.266708333333334,"audioEndSeconds":33.47291666666667},{"speaker":"A","text":"Is there an afternoon train that departs around two o clock because my meeting starts later?","position":7,"audioStartSeconds":33.672916666666666,"audioEndSeconds":38.904875},{"speaker":"B","text":"There is a direct service leaving at two fifteen when all standard seats are still available.","position":8,"audioStartSeconds":39.104875,"audioEndSeconds":44.64608333333333},{"speaker":"A","text":"That timing works perfectly for me if the journey takes less than three hours.","position":9,"audioStartSeconds":44.84608333333333,"audioEndSeconds":49.76875},{"speaker":"B","text":"It takes two hours and forty minutes so you will arrive well before your meeting begins.","position":10,"audioStartSeconds":49.96875,"audioEndSeconds":55.033208333333334},{"speaker":"A","text":"Should I pay the extra fee by cash or can I use my credit card?","position":11,"audioStartSeconds":55.23320833333333,"audioEndSeconds":59.485791666666664},{"speaker":"B","text":"You can use either payment method though contactless card payment is much faster today.","position":12,"audioStartSeconds":59.68579166666667,"audioEndSeconds":64.91775},{"speaker":"A","text":"I will tap my card on the machine since I prefer not to carry heavy coins.","position":13,"audioStartSeconds":65.11775,"audioEndSeconds":70.014625},{"speaker":"B","text":"The transaction is complete because I just printed your updated ticket for the afternoon departure.","position":14,"audioStartSeconds":70.214625,"audioEndSeconds":76.05225},{"speaker":"A","text":"Thank you for your kind help since I was worried about losing my money completely.","position":15,"audioStartSeconds":76.25225,"audioEndSeconds":81.09479166666667},{"speaker":"B","text":"You are very welcome and please have a safe journey on the afternoon service.","position":16,"audioStartSeconds":81.29479166666667,"audioEndSeconds":85.85508333333334}],"questions":[{"prompt":"What is the main purpose of the traveler visiting the ticket office?","options":["To buy a brand new ticket.","To change an unused ticket.","To ask for a complete refund."],"answer":"B","evidenceSentence":1,"evidence":"I missed my morning train I need to change this ticket for a later service","explanation":"Người hành khách đến để đổi vé chuyến sáng đã lỡ sang một chuyến muộn hơn trong ngày."},{"prompt":"What condition does the employee mention regarding standard tickets?","options":["They require a small fee for changes.","They cannot be changed after morning.","They must be bought online in advance."],"answer":"A","evidenceSentence":2,"evidence":"standard tickets usually charge a small administration fee for any changes","explanation":"Nhân viên thông báo rằng vé tiêu chuẩn thường tính một khoản phí quản lý nhỏ khi thay đổi."},{"prompt":"How does the traveler share his reservation details with the employee?","options":["By showing a printed paper receipt.","By explaining his meeting schedule.","By providing his passport details."],"answer":"A","evidenceSentence":5,"evidence":"Here is my card and my booking reference is printed right at the top of the paper receipt","explanation":"Hành khách cung cấp mã đặt chỗ được in ở phần đầu của biên nhận giấy."},{"prompt":"Which afternoon train option does the employee suggest to the traveler?","options":["A train leaving at two o clock.","A direct service at two fifteen.","A slower train with many stops."],"answer":"B","evidenceSentence":8,"evidence":"There is a direct service leaving at two fifteen when all standard seats are still available","explanation":"Nhân viên đề xuất chuyến tàu trực tiếp khởi hành lúc hai giờ mười lăm phút."},{"prompt":"How does the traveler prefer to pay for the administration fee?","options":["He pays with heavy coins.","He uses a contactless card.","He pays exact cash amount."],"answer":"B","evidenceSentence":13,"evidence":"I will tap my card on the machine since I prefer not to carry heavy coins","explanation":"Hành khách quyết định chạm thẻ lên máy thanh toán để tránh dùng tiền xu."},{"prompt":"What is the final outcome for the traveler after paying the fee?","options":["To wait for the morning train.","To collect the updated ticket.","To cancel the trip entirely."],"answer":"B","evidenceSentence":14,"evidence":"The transaction is complete because I just printed your updated ticket for the afternoon departure","explanation":"Bước tiếp theo là nhận tấm vé đã được cập nhật cho chuyến đi buổi chiều từ nhân viên."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
